cssCode:
.butterfly-svg {
  position: absolute; width: 40px; height: 40px;
  pointer-events: none; transform: translate(-50%, -50%);
  transition: top 0.1s ease-out, left 0.1s ease-out, transform 0.2s;
  filter: drop-shadow(0 0 10px #00d2ff); z-index: 100;
}
.bf-wing {
  fill: rgba(0, 210, 255, 0.4); stroke: #00d2ff; stroke-width: 2;
  transform-origin: center; animation: flapWings 0.2s infinite alternate;
}
.bf-trail {
  position: absolute; width: 8px; height: 8px; background: #00d2ff;
  border-radius: 50%; pointer-events: none; filter: blur(2px);
  animation: fadeBFTrail 1s forwards;
}
@keyframes flapWings { 0% { transform: scaleX(1); } 100% { transform: scaleX(0.3); } }
@keyframes fadeBFTrail { 0% { opacity: 0.8; transform: scale(1); } 100% { opacity: 0; transform: scale(0.2); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;touch-action:none;';

const bf = document.createElementNS("http://www.w3.org/2000/svg", "svg");
bf.setAttribute("class", "butterfly-svg");
bf.setAttribute("viewBox", "0 0 100 100");
bf.innerHTML = `
  <path class="bf-wing" d="M50 50 Q20 10 10 40 Q30 70 50 50 Z" />
  <path class="bf-wing" d="M50 50 Q80 10 90 40 Q70 70 50 50 Z" />
`;
c.appendChild(bf);

let lastX = 50, lastY = 50;

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  // Angle calculate karvo jethi butterfly mouse ni disha ma fare
  const angle = Math.atan2(y - lastY, x - lastX) * 180 / Math.PI;
  bf.style.left = `${x}px`;
  bf.style.top = `${y}px`;
  bf.style.transform = `translate(-50%, -50%) rotate(${angle + 90}deg)`;

  lastX = x; lastY = y;

  // Trail effect
  if (Math.random() > 0.5) {
    const trail = document.createElement('div');
    trail.className = 'bf-trail';
    trail.style.left = `${x}px`; trail.style.top = `${y}px`;
    c.appendChild(trail);
    setTimeout(() => trail.remove(), 1000);
  }
});
